    Mockito.when(_pinotHelixTaskResourceManager.getTaskTypes()).thenReturn(ImmutableSet.of());
    _taskMetricsEmitter.runTask(null);
    Assert.assertEquals(metricsRegistry.allMetrics().size(), 1);
    Assert.assertTrue(metricsRegistry.allMetrics().containsKey(new YammerMetricName(ControllerMetrics.class, "pinot.controller.onlineMinionInstances")));
}

@Test
public void taskType1ButNoInProgressTask() {
    PinotMetricsRegistry metricsRegistry = _controllerMetrics.getMetricsRegistry();
    String taskType = "taskType1";
    Mockito.when(_pinotHelixTaskResourceManager.getTaskTypes()).thenReturn(ImmutableSet.of(taskType));
    Mockito.when(_pinotHelixTaskResourceManager.getTasksInProgress(taskType)).thenReturn(ImmutableSet.of());
    _taskMetricsEmitter.runTask(null);
    Assert.assertEquals(metricsRegistry.allMetrics().size(), 11);
    Assert.assertTrue(metricsRegistry.allMetrics().containsKey(new YammerMetricName(ControllerMetrics.class, "pinot.controller.onlineMinionInstances")));
    Assert.assertEquals(((YammerSettableGauge<?>) metricsRegistry.allMetrics().get(new YammerMetricName(ControllerMetrics.class, "pinot.controller.numMinionTasksInProgress.taskType1")).getMetric()).value(), 0L);
    Assert.assertEquals(((YammerSettableGauge<?>) metricsRegistry.allMetrics().get(new YammerMetricName(ControllerMetrics.class, "pinot.controller.numMinionSubtasksRunning.taskType1")).getMetric()).value(), 0L);
    Assert.assertEquals(((YammerSettableGauge<?>) metricsRegistry.allMetrics().get(new YammerMetricName(ControllerMetrics.class, "pinot.controller.numMinionSubtasksWaiting.taskType1")).getMetric()).value(), 0L);
