private PinotHelixResourceManager setupSegmentMetadata(TableConfig tableConfig, final long now, final int nSegments, List<String> segmentsToBeDeleted) {
    final int replicaCount = tableConfig.getReplication();
    List<SegmentZKMetadata> segmentsZKMetadata = new ArrayList<>();
    IdealState idealState = PinotTableIdealStateBuilder.buildEmptyIdealStateFor(REALTIME_TABLE_NAME, replicaCount, true);
