@Test
public void differentUpstreamStatsProduceEmptyStats() throws IOException {
    when(_mailboxService.getReceivingMailbox(eq(MAILBOX_ID_1))).thenReturn(_mailbox1);
    List<DataBuffer> stats1 = new MultiStageQueryStats.Builder(1).addLast(open -> open.addLastOperator(Type.MAILBOX_SEND, new StatMap<>(MailboxSendOperator.StatKey.class)).addLastOperator(Type.LEAF, new StatMap<>(LeafStageTransferableBlockOperator.StatKey.class)).close()).build().serialize();
    ReceivingMailbox.MseBlockWithStats block1 = OperatorTestUtil.eosWithStats(stats1);
    when(_mailbox1.poll()).thenReturn(block1);
    when(_mailboxService.getReceivingMailbox(eq(MAILBOX_ID_2))).thenReturn(_mailbox2);
    List<DataBuffer> stats2 = new MultiStageQueryStats.Builder(1).addLast(open -> open.addLastOperator(Type.MAILBOX_SEND, new StatMap<>(MailboxSendOperator.StatKey.class)).addLastOperator(Type.FILTER, new StatMap<>(FilterOperator.StatKey.class)).addLastOperator(Type.LEAF, new StatMap<>(LeafStageTransferableBlockOperator.StatKey.class)).close()).build().serialize();
    ReceivingMailbox.MseBlockWithStats block2 = OperatorTestUtil.eosWithStats(stats2);
    when(_mailbox2.poll()).thenReturn(block2);
    try (MailboxReceiveOperator operator = getOperator(_stageMetadataBoth, RelDistribution.Type.SINGLETON)) {
        while (!operator.nextBlock().isEos()) {
            // drain
        }
        MultiStageQueryStats stats = operator.calculateStats();
        MultiStageQueryStats.StageStats.Closed upstreamStats = stats.getUpstreamStageStats(1);
        assertNull(upstreamStats, "Upstream stats should be null in case of error merging stats");
    }
}

