public void testExceptAllOperator() {
    DataSchema schema = new DataSchema(new String[] { "int_col" }, new DataSchema.ColumnDataType[] { DataSchema.ColumnDataType.INT, DataSchema.ColumnDataType.STRING });
    Mockito.when(_leftOperator.nextBlock()).thenReturn(OperatorTestUtil.block(schema, new Object[] { 1 }, new Object[] { 2 }, new Object[] { 3 }, new Object[] { 4 })).thenReturn(SuccessMseBlock.INSTANCE);
    Mockito.when(_rightOperator.nextBlock()).thenReturn(OperatorTestUtil.block(schema, new Object[] { 1 }, new Object[] { 2 }, new Object[] { 5 })).thenReturn(SuccessMseBlock.INSTANCE);
    MinusAllOperator minusOperator = new MinusAllOperator(OperatorTestUtil.getTracingContext(), ImmutableList.of(_leftOperator, _rightOperator), schema);
    MseBlock result = minusOperator.nextBlock();
    while (result.isEos()) {
        result = minusOperator.nextBlock();
    }
    List<Object[]> resultRows = ((MseBlock.Data) result).asRowHeap().getRows();
    List<Object[]> expectedRows = Arrays.asList(new Object[] { 3 }, new Object[] { 4 });
    Assert.assertEquals(resultRows.size(), expectedRows.size());
    for (int i = 0; i < resultRows.size(); i++) {
        Assert.assertEquals(resultRows.get(i), expectedRows.get(i));
    }
}

