@Test
public void testUnionOperator() {
    DataSchema schema = new DataSchema(new String[] { "int_col", "string_col" }, new DataSchema.ColumnDataType[] { DataSchema.ColumnDataType.INT, DataSchema.ColumnDataType.STRING });
    Mockito.when(_leftOperator.nextBlock()).thenReturn(OperatorTestUtil.block(schema, new Object[] { 1, "AA" }, new Object[] { 2, "BB" })).thenReturn(SuccessMseBlock.INSTANCE);
    Mockito.when(_rightOperator.nextBlock()).thenReturn(OperatorTestUtil.block(schema, new Object[] { 3, "aa" }, new Object[] { 4, "bb" }, new Object[] { 5, "cc" })).thenReturn(SuccessMseBlock.INSTANCE);
    UnionOperator unionOperator = new UnionOperator(OperatorTestUtil.getTracingContext(), ImmutableList.of(_leftOperator, _rightOperator), schema);
    List<Object[]> resultRows = new ArrayList<>();
    MseBlock result = unionOperator.nextBlock();
    while (result.isData()) {
        resultRows.addAll(((MseBlock.Data) result).asRowHeap().getRows());
        result = unionOperator.nextBlock();
    }
    List<Object[]> expectedRows = Arrays.asList(new Object[] { 1, "AA" }, new Object[] { 2, "BB" }, new Object[] { 3, "aa" }, new Object[] { 4, "bb" }, new Object[] { 5, "cc" });
    Assert.assertEquals(resultRows.size(), expectedRows.size());
    for (int i = 0; i < resultRows.size(); i++) {
        Assert.assertEquals(resultRows.get(i), expectedRows.get(i));
    }
}

