public void testShouldHandleWindowWithPartialResultsWhenHitDataRowsLimit() {
    // Given:
    DataSchema inputSchema = new DataSchema(new String[] { "group", "arg" }, new ColumnDataType[] { INT, INT });
    MultiStageOperator input = new BlockListMultiStageOperator.Builder(inputSchema).spied().addBlock(new Object[] { 2, 1 }).addBlock(new Object[] { 3, 4 }).buildWithEos();
    DataSchema resultSchema = new DataSchema(new String[] { "group", "arg", "sum" }, new ColumnDataType[] { INT, INT, DOUBLE });
    List<Integer> keys = List.of(0);
    List<RexExpression.FunctionCall> aggCalls = List.of(getSum(new RexExpression.InputRef(1)));
    PlanNode.NodeHint nodeHint = new PlanNode.NodeHint(Map.of(PinotHintOptions.WINDOW_HINT_OPTIONS, Map.of(PinotHintOptions.WindowHintOptions.WINDOW_OVERFLOW_MODE, "BREAK", PinotHintOptions.WindowHintOptions.MAX_ROWS_IN_WINDOW, "1")));
    WindowAggregateOperator operator = getOperator(inputSchema, resultSchema, keys, List.of(), aggCalls, WindowNode.WindowFrameType.RANGE, Integer.MIN_VALUE, Integer.MAX_VALUE, nodeHint, input);
    // When:
    List<Object[]> resultRows = ((MseBlock.Data) operator.nextBlock()).asRowHeap().getRows();
    // Then:
    verify(input).earlyTerminate();
    assertEquals(resultRows.size(), 1);
    assertEquals(resultRows.get(0), new Object[] { 2, 1, 1.0 });
    MseBlock block2 = operator.nextBlock();
