    StatMap<WindowAggregateOperator.StatKey> windowStats = OperatorTestUtil.getStatMap(WindowAggregateOperator.StatKey.class, operator.calculateStats());
    assertTrue(windowStats.getBoolean(WindowAggregateOperator.StatKey.MAX_ROWS_IN_WINDOW_REACHED), "Max rows in window should be reached");
}

