    _mutableSegment = MutableSegmentImplTestUtils.createMutableSegmentImpl(schema, Collections.emptySet(), Collections.emptySet(), new HashSet<>(Arrays.asList(INT_COL, STRING_COL)), Collections.singletonMap(JSON_COL, new JsonIndexConfig()), _serverMetrics);
