public static MutableSegmentImpl createMutableSegmentImpl(Schema schema, Set<String> noDictionaryColumns, Set<String> varLengthDictionaryColumns, Set<String> invertedIndexColumns, Map<String, JsonIndexConfig> jsonIndexConfigs, boolean aggregateMetrics, @Nullable List<AggregationConfig> aggregationConfigs, boolean nullHandlingEnabled, @Nullable String timeColumnName, @Nullable PartitionUpsertMetadataManager partitionUpsertMetadataManager, @Nullable PartitionDedupMetadataManager partitionDedupMetadataManager, @Nullable ServerMetrics serverMetrics) {
    RealtimeSegmentStatsHistory statsHistory = mock(RealtimeSegmentStatsHistory.class);
    when(statsHistory.getEstimatedCardinality(anyString())).thenReturn(200);
    when(statsHistory.getEstimatedAvgColSize(anyString())).thenReturn(32);
    DictionaryIndexConfig varLengthDictConf = new DictionaryIndexConfig(false, true);
    RealtimeSegmentConfig.Builder segmentConfBuilder = new RealtimeSegmentConfig.Builder().setTableNameWithType(TABLE_NAME_WITH_TYPE).setSegmentName(SEGMENT_NAME).setStreamName(STREAM_NAME).setSchema(schema).setTimeColumnName(timeColumnName).setCapacity(100000).setAvgNumMultiValues(2).setIndex(noDictionaryColumns, StandardIndexes.dictionary(), DictionaryIndexConfig.DISABLED).setIndex(varLengthDictionaryColumns, StandardIndexes.dictionary(), varLengthDictConf).setIndex(invertedIndexColumns, StandardIndexes.inverted(), IndexConfig.ENABLED).setSegmentZKMetadata(new SegmentZKMetadata(SEGMENT_NAME)).setMemoryManager(new DirectMemoryManager(SEGMENT_NAME)).setStatsHistory(statsHistory).setAggregateMetrics(aggregateMetrics).setIngestionAggregationConfigs(aggregationConfigs).setDefaultNullHandlingEnabled(nullHandlingEnabled).setPartitionUpsertMetadataManager(partitionUpsertMetadataManager).setPartitionDedupMetadataManager(partitionDedupMetadataManager).setConsumerDir(TEMP_DIR.getAbsolutePath() + "/" + UUID.randomUUID() + "/consumerDir");
    for (Map.Entry<String, JsonIndexConfig> entry : jsonIndexConfigs.entrySet()) {
        segmentConfBuilder.setIndex(entry.getKey(), StandardIndexes.json(), entry.getValue());
    }
    RealtimeSegmentConfig realtimeSegmentConfig = segmentConfBuilder.build();
    return new MutableSegmentImpl(realtimeSegmentConfig, serverMetrics);
}

