public void testWithEmptyDir() throws Exception {
    // segmentDir does not have anything to begin with
    assertEquals(TEMP_DIR.list().length, 0);
    final byte[] dataBytes;
    try (SingleFileIndexDirectory columnDirectory = new SingleFileIndexDirectory(TEMP_DIR, _segmentMetadata, ReadMode.mmap);
        PinotDataBuffer writtenBuffer = columnDirectory.newBuffer("foo", StandardIndexes.dictionary(), 1024)) {
        String data = "This is a test string";
        dataBytes = data.getBytes();
        int pos = 0;
        for (byte b : dataBytes) {
            writtenBuffer.putByte(pos++, b);
        }
    }
    Mockito.when(_segmentMetadata.getAllColumns()).thenReturn(new TreeSet<>(Arrays.asList("foo")));
    try (SingleFileIndexDirectory directoryReader = new SingleFileIndexDirectory(TEMP_DIR, _segmentMetadata, ReadMode.mmap);
        PinotDataBuffer readBuffer = directoryReader.getBuffer("foo", StandardIndexes.dictionary())) {
        assertEquals(1024, readBuffer.size());
        int length = dataBytes.length;
        for (int i = 0; i < length; i++) {
            byte b = readBuffer.getByte(i);
            assertEquals(dataBytes[i], b);
        }
    }
}

@Test
public void testGetColumnIndices() throws Exception {
    TextIndexConfig config = new TextIndexConfig(false, null, null, false, false, null, null, true, 500, null, null, null, null, false, false, 0, false, null);
    try (SingleFileIndexDirectory sfd = new SingleFileIndexDirectory(TEMP_DIR, _segmentMetadata, ReadMode.mmap);
        LuceneTextIndexCreator fooCreator = new LuceneTextIndexCreator("foo", TEMP_DIR, true, false, null, null, config);
        LuceneTextIndexCreator barCreator = new LuceneTextIndexCreator("bar", TEMP_DIR, true, false, null, null, config)) {
        PinotDataBuffer buf = sfd.newBuffer("col1", StandardIndexes.forward(), 1024);
        buf.putInt(0, 111);
        buf = sfd.newBuffer("col2", StandardIndexes.dictionary(), 1024);
        buf.putInt(0, 222);
        buf = sfd.newBuffer("col3", StandardIndexes.forward(), 1024);
        buf.putInt(0, 333);
        buf = sfd.newBuffer("col4", StandardIndexes.inverted(), 1024);
        buf.putInt(0, 444);
        buf = sfd.newBuffer("col5", StandardIndexes.h3(), 1024);
        buf.putInt(0, 555);
        fooCreator.add("{\"clean\":\"this\"}");
        fooCreator.seal();
        barCreator.add("{\"retain\":\"this\"}");
        barCreator.add("{\"keep\":\"this\"}");
        barCreator.add("{\"hold\":\"this\"}");
        barCreator.seal();
    }
    // Need segmentMetadata to tell the full set of columns in this segment.
    when(_segmentMetadata.getAllColumns()).thenReturn(new TreeSet<>(Arrays.asList("col1", "col2", "col3", "col4", "foo", "bar")));
    try (SingleFileIndexDirectory sfd = new SingleFileIndexDirectory(TEMP_DIR, _segmentMetadata, ReadMode.mmap)) {
        assertEquals(sfd.getColumnsWithIndex(StandardIndexes.forward()), new HashSet<>(Arrays.asList("col1", "col3")));
        assertEquals(sfd.getColumnsWithIndex(StandardIndexes.dictionary()), new HashSet<>(Collections.singletonList("col2")));
        assertEquals(sfd.getColumnsWithIndex(StandardIndexes.inverted()), new HashSet<>(Collections.singletonList("col4")));
        assertEquals(sfd.getColumnsWithIndex(StandardIndexes.h3()), new HashSet<>(Collections.singletonList("col5")));
        assertEquals(sfd.getColumnsWithIndex(StandardIndexes.text()), new HashSet<>(Arrays.asList("foo", "bar")));
        sfd.removeIndex("col1", StandardIndexes.forward());
        sfd.removeIndex("col2", StandardIndexes.dictionary());
        sfd.removeIndex("col5", StandardIndexes.h3());
        sfd.removeIndex("foo", StandardIndexes.text());
        sfd.removeIndex("col111", StandardIndexes.dictionary());
        assertEquals(sfd.getColumnsWithIndex(StandardIndexes.forward()), new HashSet<>(Collections.singletonList("col3")));
        assertEquals(sfd.getColumnsWithIndex(StandardIndexes.dictionary()), new HashSet<>(Collections.emptySet()));
        assertEquals(sfd.getColumnsWithIndex(StandardIndexes.inverted()), new HashSet<>(Collections.singletonList("col4")));
        assertEquals(sfd.getColumnsWithIndex(StandardIndexes.h3()), new HashSet<>(Collections.emptySet()));
        assertEquals(sfd.getColumnsWithIndex(StandardIndexes.text()), new HashSet<>(Collections.singletonList("bar")));
    }
}

