private void downLoadAndVerifyValidDocIdsSnapshot(String tableNameWithType, ImmutableSegmentImpl segment) throws IOException {
    String snapshotPath = "/segments/" + tableNameWithType + "/" + segment.getSegmentName() + "/validDocIds";
    PartitionUpsertMetadataManager upsertMetadataManager = mock(PartitionUpsertMetadataManager.class);
    ThreadSafeMutableRoaringBitmap validDocIds = new ThreadSafeMutableRoaringBitmap();
    ThreadSafeMutableRoaringBitmap queryableDocIds = new ThreadSafeMutableRoaringBitmap();
    ThreadSafeMutableRoaringBitmap validDocIdsSnapshot = new ThreadSafeMutableRoaringBitmap();
    int[] docIds = new int[] { 1, 4, 6, 10, 15, 17, 18, 20 };
    for (int docId : docIds) {
        validDocIds.add(docId);
        queryableDocIds.add(docId + 1);
        validDocIdsSnapshot.add(docId + 2);
    }
    segment.enableUpsert(upsertMetadataManager, validDocIds, queryableDocIds);
    File validDocIdsSnapshotFile = new File(SegmentDirectoryPaths.findSegmentDirectory(segment.getSegmentMetadata().getIndexDir()), V1Constants.VALID_DOC_IDS_SNAPSHOT_FILE_NAME);
    FileUtils.writeByteArrayToFile(validDocIdsSnapshotFile, RoaringBitmapUtils.serialize(validDocIdsSnapshot.getMutableRoaringBitmap()));
    // Check no type (default should be validDocIdsSnapshot)
    Response response = _webTarget.path(snapshotPath).request().get(Response.class);
    Assert.assertEquals(response.getStatus(), Response.Status.OK.getStatusCode());
    byte[] validDocIdsSnapshotBitmap = response.readEntity(byte[].class);
    Assert.assertNotNull(validDocIdsSnapshotBitmap);
    Assert.assertEquals(new ImmutableRoaringBitmap(ByteBuffer.wrap(validDocIdsSnapshotBitmap)).toMutableRoaringBitmap(), validDocIdsSnapshot.getMutableRoaringBitmap());
    // Check snapshot type
    response = _webTarget.path(snapshotPath).queryParam("validDocIdsType", ValidDocIdsType.SNAPSHOT.toString()).request().get(Response.class);
    Assert.assertEquals(response.getStatus(), Response.Status.OK.getStatusCode());
    validDocIdsSnapshotBitmap = response.readEntity(byte[].class);
    Assert.assertNotNull(validDocIdsSnapshotBitmap);
    Assert.assertEquals(new ImmutableRoaringBitmap(ByteBuffer.wrap(validDocIdsSnapshotBitmap)).toMutableRoaringBitmap(), validDocIdsSnapshot.getMutableRoaringBitmap());
    // Check onHeap type
    response = _webTarget.path(snapshotPath).queryParam("validDocIdsType", ValidDocIdsType.IN_MEMORY).request().get(Response.class);
    Assert.assertEquals(response.getStatus(), Response.Status.OK.getStatusCode());
    validDocIdsSnapshotBitmap = response.readEntity(byte[].class);
    Assert.assertNotNull(validDocIdsSnapshotBitmap);
    Assert.assertEquals(new ImmutableRoaringBitmap(ByteBuffer.wrap(validDocIdsSnapshotBitmap)).toMutableRoaringBitmap(), validDocIds.getMutableRoaringBitmap());
    // Check onHeapWithDelete type
    response = _webTarget.path(snapshotPath).queryParam("validDocIdsType", ValidDocIdsType.IN_MEMORY_WITH_DELETE.toString()).request().get(Response.class);
    Assert.assertEquals(response.getStatus(), Response.Status.OK.getStatusCode());
    validDocIdsSnapshotBitmap = response.readEntity(byte[].class);
    Assert.assertNotNull(validDocIdsSnapshotBitmap);
    Assert.assertEquals(new ImmutableRoaringBitmap(ByteBuffer.wrap(validDocIdsSnapshotBitmap)).toMutableRoaringBitmap(), queryableDocIds.getMutableRoaringBitmap());
}

