    setupLatestIngestionTimestamp(segMngrA0, Long.MIN_VALUE);
    //              current offset          latest stream offset    current time    last ingestion time
    // segA0              0                       20                     100               Long.MIN_VALUE
    // segA1 (segment is absent)
