@Test
public void segmentBeingCommmitted() {
    String segA0 = "tableA__0__0__123Z";
    String segA1 = "tableA__1__0__123Z";
    String segB0 = "tableB__0__0__123Z";
    Map<String, Set<String>> consumingSegments = new HashMap<>();
